#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    string s;
    cin >> s;

    int nk = 0, nv = 0, no = 0;
    vector<int> kpos(n), vpos(n), opos(n);
    vector<int> snk(n + 1, 0), snv(n + 1, 0), sno(n + 1, 0);

    for (int i = 0; i < n; i++) {
        char ch = s[i];
        if (ch == 'V') {
            vpos[nv++] = i;
        } else if (ch == 'K') {
            kpos[nk++] = i;
        } else {
            opos[no++] = i;
        }
        snk[i + 1] = nk;
        snv[i + 1] = nv;
        sno[i + 1] = no;
    }

    const int INF = 1000000000;
    vector<vector<vector<vector<int>>>> best(2, vector<vector<vector<int>>>(nk + 1, vector<vector<int>>(nv + 1, vector<int>(no + 1, INF))));
    best[0][0][0][0] = 0;

    for (int k = 0; k <= nk; k++) {
        for (int v = 0; v <= nv; v++) {
            for (int o = 0; o <= no; o++) {
                for (int hv = 0; hv < 2; hv++) {
                    int cur = best[hv][k][v][o];
                    if (cur == INF) continue;
                    if (k < nk && hv == 0) {
                        int cost = cur + max(snv[kpos[k]] - v, 0) + max(sno[kpos[k]] - o, 0);
                        if (cost < best[0][k + 1][v][o]) {
                            best[0][k + 1][v][o] = cost;
                        }
                    }
                    if (v < nv) {
                        int cost = cur + max(snk[vpos[v]] - k, 0) + max(sno[vpos[v]] - o, 0);
                        if (cost < best[1][k][v + 1][o]) {
                            best[1][k][v + 1][o] = cost;
                        }
                    }
                    if (o < no) {
                        int cost = cur + max(snv[opos[o]] - v, 0) + max(snk[opos[o]] - k, 0);
                        if (cost < best[0][k][v][o + 1]) {
                            best[0][k][v][o + 1] = cost;
                        }
                    }
                }
            }
        }
    }

    int answer = min(best[0][nk][nv][no], best[1][nk][nv][no]);
    cout << answer << "\n";

    return 0;
}
